import type { ColorThemes } from './build-color-themes'
import type { Scales } from './build-scales'

export type TokenSet = ColorThemes & Scales

const HEADER = `/**
 * GENERATED by scripts/tokens/generate-tokens.ts from packages/tailwind/src — do not edit.
 * Run \`pnpm --filter @bitrate/mobile tokens\` after changing a token there.
 */
`

const literal = (value: unknown) => JSON.stringify(value, null, 2).replace(/"([A-Za-z_]\w*)":/g, '$1:')

/** Renders the token set as a TypeScript module with `as const` objects. */
export function renderTokensModule(tokens: TokenSet): string {
  const sections = [
    ['colorThemes', tokens.themes],
    ['brandColors', tokens.brand],
    ['spacing', tokens.spacing],
    ['radius', tokens.radius],
    ['fontSize', tokens.fontSize],
    ['fontWeight', tokens.fontWeight],
  ] as const

  const body = sections.map(([name, value]) => `export const ${name} = ${literal(value)} as const\n`)
  return `${HEADER}\n${body.join('\n')}`
}
